<?php
use App\Domain\Identity\Enums\UserStatus;use App\Models\Permission;use App\Models\User;use Database\Seeders\AuthorizationSeeder;use Database\Seeders\ModuleSeeder;use Illuminate\Support\Str;
it('lets a platform admin create an isolated tenant with an owner', function(){ $this->seed(AuthorizationSeeder::class);$this->seed(ModuleSeeder::class); $admin=User::factory()->create(['tenant_id'=>null,'is_platform_admin'=>true,'status'=>UserStatus::Active]);$token=$admin->createToken('test')->plainTextToken;$this->withToken($token)->postJson('/api/v1/platform/tenants',['slug'=>'alpha','legal_name'=>'Alpha LLC','display_name'=>'Alpha','organization_email'=>'info@alpha.test','owner_name'=>'Owner','owner_email'=>'owner@alpha.test','owner_password'=>'VeryStrongPassword!'])->assertSuccessful()->assertJsonPath('data.slug','alpha');$this->assertDatabaseHas('tenants',['slug'=>'alpha']);$this->assertDatabaseHas('users',['email'=>'owner@alpha.test','is_platform_admin'=>false]); });
